// Nodes 210 and 211 must already exist in this model.
var start = new Node(210, 0, 0, 0);
var end = new Node(211, 4.5, 0, 0);
geometry.CreateMultipleBeamsExtended(geometry.Wrapper.Root,
    new[] { new Beam(310, start, end) });

// Use IDs that are unused in the target model; coordinates use its input units.
geometry.CreateMultipleNodesExtended(geometry.Wrapper.Root, new[]
{
    new Node(210, 0, 0, 0),
    new Node(211, 4.5, 0, 0)
});

// Both IDs must exist and be suitable for merging in the target model.
var retain = new Node(210, 0, 0, 0);
var redundant = new Node(212, 0, 0, 0);
geometry.MergeNodesExtended(geometry.Wrapper.Root, retain,
    new[] { retain, redundant });

// Primary case 17 and reference case 41 must already exist.
load.AddReferenceLoadsTo(17, new System.Collections.Generic.Dictionary<int, double>
{
    { 41, 1.25 }
});

// Primary target 17 and suitable source cases 41 and 42 must already exist.
load.AddRepeatLoadsTo(17, new System.Collections.Generic.Dictionary<int, double>
{
    { 41, 1.5 },
    { 42, -0.75 }
});
